CREATE POLICY "avatars owner or workspace member read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'avatars' AND (storage.foldername(name))[1] IN (SELECT p.id::text FROM public.profiles p WHERE p.id = auth.uid() OR EXISTS (SELECT 1 FROM public.workspace_members mine JOIN public.workspace_members teammate ON teammate.workspace_id = mine.workspace_id WHERE mine.user_id = auth.uid() AND teammate.user_id = p.id)));
ALTER POLICY "avatars own insert" ON storage.objects TO authenticated WITH CHECK (bucket_id = 'avatars' AND (storage.foldername(name))[1] = auth.uid()::text AND lower(storage.extension(name)) IN ('png','jpg','jpeg','webp','gif'));
ALTER POLICY "avatars own update" ON storage.objects TO authenticated USING (bucket_id = 'avatars' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'avatars' AND (storage.foldername(name))[1] = auth.uid()::text AND lower(storage.extension(name)) IN ('png','jpg','jpeg','webp','gif'));
ALTER POLICY "avatars own delete" ON storage.objects TO authenticated USING (bucket_id = 'avatars' AND (storage.foldername(name))[1] = auth.uid()::text);